const MAINTENANCE = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>\u5b95\u673a\u4e2d \u00b7 \u8bf7\u7a0d\u540e</title>\n<meta name=\"description\" content=\"\u672c\u7ad9\u6b63\u5728\u7ef4\u62a4\u4e2d\u2026\u2026 \u5b95\u673a\u4e2d\uff0c\u8bf7\u7a0d\u540e\u518d\u6765\u3002\">\n<meta name=\"robots\" content=\"noindex\">\n<meta name=\"theme-color\" content=\"#E2B934\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23E2B934'/%3E%3Cstop offset='1' stop-color='%23A893D8'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='100' height='100' rx='24' fill='url(%23g)'/%3E%3Ctext x='50' y='77' font-size='64' text-anchor='middle'%3E%F0%9F%90%BE%3C/text%3E%3C/svg%3E\">\n<style>\n  :root{\n    --gold:#E2B934;\n    --gold-deep:#C2951E;\n    --plum:#3E3571;\n    --plum-l:#6E6A96;\n    --ink:#56507f;\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html,body{height:100%}\n  body{\n    font-family:\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",\"Noto Sans SC\",\"Source Han Sans SC\",system-ui,sans-serif;\n    color:var(--ink); overflow:hidden; background:#eef0f5; -webkit-font-smoothing:antialiased;\n  }\n  .bg{position:fixed; inset:0; z-index:0}\n  .bg img{width:100%;height:100%;object-fit:cover;object-position:center;display:block;\n    animation:kenburns 26s ease-in-out infinite alternate}\n  @keyframes kenburns{from{transform:scale(1)}to{transform:scale(1.05)}}\n\n  /* \u6587\u5b57\u533a\u6696\u5149 */\n  .soft{position:fixed; inset:0; z-index:1; pointer-events:none;\n    background:radial-gradient(50% 34% at 50% 66%, rgba(255,242,196,.5), rgba(255,255,255,.10) 60%, transparent 80%)}\n  .veil{position:fixed; inset:0; z-index:1; pointer-events:none;\n    background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,0) 30%, rgba(255,255,255,0) 62%, rgba(255,252,240,.07))}\n\n  /* \u6574\u4f53\u6587\u5b57\u5757\uff08\u4f4d\u7f6e\u9760\u4e0b\uff0c\u907f\u5f00\u8138\uff09 */\n  .stage{position:fixed; left:0; right:0; top:68%; z-index:3;\n    transform:translateY(-50%); text-align:center; padding:0 16px; pointer-events:none}\n\n  /* \u4e3b\u89d2\uff1a\u5927\u53f7\u989c\u6587\u5b57\uff08\u8f6e\u6362\uff09 */\n  .hero{min-height:1.3em; font-size:clamp(46px,10vw,96px); font-weight:900;\n    line-height:1.1; white-space:nowrap; font-style:normal; color:var(--plum);\n    text-shadow:0 0 4px rgba(255,255,255,.95), 0 0 12px rgba(255,255,255,.9), 0 0 22px rgba(255,255,255,.5),\n                0 3px 10px rgba(60,50,110,.28);\n    opacity:0}\n  .hero.pop{opacity:1; animation:heroIn .55s ease}\n  @keyframes heroIn{from{opacity:0; transform:translateY(14px) scale(.92); filter:blur(5px)}\n                    to{opacity:1; transform:none; filter:blur(0)}}\n\n  .hcap{min-height:1.5em; margin-top:4px; font-size:clamp(14px,2.4vw,22px); font-weight:600;\n    color:var(--ink); letter-spacing:.16em; opacity:0}\n  .hcap.pop{opacity:1; animation:hcapIn .5s ease}\n  @keyframes hcapIn{from{opacity:0; transform:translateY(7px)}to{opacity:1; transform:none}}\n\n  .divider{width:min(44vw,240px); height:1px; margin:clamp(12px,2vh,20px) auto clamp(10px,1.6vh,16px);\n    background:linear-gradient(90deg, transparent, rgba(194,149,30,.55), rgba(110,106,150,.45), transparent)}\n\n  /* \u6253\u5370\u673a\u4e00\u53e5\u5230\u5e95\uff1a\u5b95\u673a\u4e2d... \u8bf7\u7a0d\u540e...\uff08\u540c\u4e00\u884c\u8fde\u7740\u6253\uff09 */\n  #typed{display:block; text-align:center; line-height:1.6}\n  #typed .seg{display:inline; white-space:nowrap}\n  #typed .tline{font-size:clamp(22px,6.6vw,84px); font-weight:900; letter-spacing:.1em; color:var(--gold);\n    text-shadow:0 0 20px rgba(255,236,160,.6), 0 2px 0 rgba(255,255,255,.32), 0 4px 14px rgba(160,120,20,.32)}\n  #typed .ch{display:inline-block; animation:print .32s ease both}\n  @keyframes print{0%{opacity:0; transform:translateY(3px); filter:blur(3px)}100%{opacity:1; transform:none; filter:blur(0)}}\n  .caret{display:inline-block; width:3px; height:.82em; vertical-align:text-bottom; margin:0 2px;\n    border-radius:2px; background:var(--gold); box-shadow:0 0 8px rgba(226,185,52,.85);\n    animation:blink .9s steps(1) infinite}\n  @keyframes blink{0%,49%{opacity:1}50%,100%{opacity:0}}\n\n  /* \u5e95\u90e8\u63a7\u5236\u6761 */\n  .bar{position:fixed; left:50%; bottom:clamp(14px,3vh,26px); transform:translateX(-50%); z-index:5;\n    display:flex; align-items:center; gap:12px; padding:8px 12px 8px 18px; border-radius:999px;\n    background:rgba(255,252,244,.6); backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);\n    border:1px solid rgba(255,255,255,.75); box-shadow:0 6px 22px -12px rgba(80,60,10,.4);\n    opacity:0; transform:translate(-50%,10px); transition:opacity .6s ease, transform .6s ease}\n  .bar.show{opacity:1; transform:translate(-50%,0)}\n  .bar .cd{font-size:13px; color:var(--plum-l); white-space:nowrap; display:flex; align-items:baseline; gap:5px}\n  .bar .cd b{font-variant-numeric:tabular-nums; font-size:15px; color:var(--gold-deep)}\n  .btn{cursor:pointer; border:1px solid rgba(226,185,52,.45); background:#fff; color:#8a6d10;\n    font:inherit; font-size:13px; font-weight:700; letter-spacing:1px; padding:8px 18px; border-radius:999px;\n    box-shadow:0 3px 10px -6px rgba(160,120,20,.45); transition:transform .16s ease, background .16s ease}\n  .btn:hover{background:#fff8e0; transform:translateY(-1px)}\n  .btn:active{transform:translateY(0) scale(.97)}\n  .btn:focus-visible{outline:3px solid rgba(226,185,52,.5); outline-offset:2px}\n\n  @media (max-width:560px){\n    .stage{top:72%}\n    .bar{gap:9px; padding-left:13px}\n  }\n  @media (prefers-reduced-motion:reduce){\n    *{animation:none!important; transition:none!important}\n    .hero,.hcap{opacity:1}\n  }\n</style>\n</head>\n<body>\n  <div class=\"bg\" aria-hidden=\"true\">\n    <img src=\"data:image/jpeg;base64,\" alt=\"\">\n  </div>\n  <div class=\"soft\" aria-hidden=\"true\"></div>\n  <div class=\"veil\" aria-hidden=\"true\"></div>\n\n  <div class=\"stage\">\n    <div class=\"hero\" id=\"hero\" aria-hidden=\"true\"></div>\n    <div class=\"hcap\" id=\"hcap\" aria-live=\"polite\"></div>\n    <div class=\"divider\" aria-hidden=\"true\"></div>\n    <h1 id=\"typed\" aria-label=\"\u5b95\u673a\u4e2d\u2026\u2026 \u8bf7\u7a0d\u540e\u2026\u2026\"></h1>\n  </div>\n\n  <div class=\"bar\" id=\"bar\">\n    <div class=\"cd\"><b id=\"cd\">30</b> \u79d2\u540e\u81ea\u52a8\u5c1d\u8bd5\u8fde\u63a5</div>\n    <button class=\"btn\" id=\"refresh\">\u7acb\u5373\u91cd\u8bd5</button>\n  </div>\n\n<script>\n(function(){\n  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var L1 = '\u5b95\u673a\u4e2d', L1D = 3;      // \u7b2c\u4e00\u884c\n  var L2 = '\u8bf7\u7a0d\u540e', L2D = 3;      // \u7b2c\u4e8c\u884c\uff08\u5728\u540e\u9762\u7ee7\u7eed\u6253\u51fa\uff09\n\n  function sleep(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }\n\n  /* \u989c\u6587\u5b57/\u6587\u6848\u4e3b\u89d2\u7ec4 */\n  var LINES = [\n    ['(\u00d7\ufe4f\u00d7)','\u670d\u52a1\u5668\u660f\u5012\u5566'],\n    ['(\uff1b\u00d7_\u00d7)','\u7cfb\u7edf\u6682\u65f6\u5931\u8054'],\n    ['(\u30fb_\u30fb\u3002)','\u6b63\u5728\u60f3\u529e\u6cd5\u2026'],\n    ['orz','\u670d\u52a1\u5668\u8dea\u4e86'],\n    ['T_T','\u545c\u545c\uff0c\u6253\u4e0d\u5f00'],\n    ['(\u30fb\u3078\u30fb)','\u52a0\u8f7d\u5931\u8d25\uff0c\u8bf7\u8fc7\u4f1a\u513f\u518d\u6765']\n  ];\n  var hero = document.getElementById('hero');\n  var hcap = document.getElementById('hcap');\n  function popHero(idx){\n    var pair = LINES[idx % LINES.length];\n    hero.textContent = pair[0];\n    hcap.textContent = pair[1];\n    [hero, hcap].forEach(function(el){\n      el.classList.remove('pop'); void el.offsetWidth; el.classList.add('pop');\n    });\n  }\n\n  /* \u6253\u5b57\u673a\u5bb9\u5668\uff1a\u5149\u6807\u56fa\u5b9a\u5728\u672b\u5c3e */\n  var typed = document.getElementById('typed');\n  var caret = document.createElement('span');\n  caret.className = 'caret';\n  typed.appendChild(caret);\n\n  function newSeg(cls){\n    var seg = document.createElement('span');\n    seg.className = 'seg ' + cls;\n    typed.insertBefore(seg, caret);   // \u7d27\u6328\u5728\u5149\u6807\u524d = \u5f53\u524d\u884c\u672b\u5c3e\n    return seg;\n  }\n  function putCh(seg, ch){\n    var s = document.createElement('span');\n    s.className = 'ch'; s.textContent = ch;\n    seg.appendChild(s);\n  }\n\n  /* \u6253\u5370\u673a\u4e00\u53e5\u5230\u5e95\uff1a\u5b95\u673a\u4e2d... + \u7a7a\u683c + \u8bf7\u7a0d\u540e...\uff08\u540c\u4e00\u884c\u8fde\u7740\u6253\uff09 */\n  var bar = document.getElementById('bar');\n  (async function type(){\n    var seg1 = newSeg('tline');\n    for (var i=0;i<L1.length;i++){\n      putCh(seg1, L1[i]);\n      if(!reduce) await sleep(400);\n    }\n    for (var d=0; d<L1D; d++){\n      putCh(seg1, '.');\n      if(!reduce) await sleep(d===2 ? 520 : 300);\n    }\n    await sleep(reduce?0:260);\n    seg1.appendChild(document.createTextNode('\u00a0\u00a0'));   // \u8bcd\u95f4\u7a7a\u683c\uff0c\u4ecd\u5728\u540c\u4e00\u884c\n\n    var seg2 = newSeg('tline');\n    for (var j=0;j<L2.length;j++){\n      putCh(seg2, L2[j]);\n      if(!reduce) await sleep(300);\n    }\n    for (var d2=0; d2<L2D; d2++){\n      putCh(seg2, '.');\n      if(!reduce) await sleep(d2===2 ? 460 : 260);\n    }\n    caret.style.display = 'none';\n    bar.classList.add('show');\n  })();\n\n  /* \u4e3b\u89d2\u8f6e\u6362 */\n  popHero(0);\n  if(!reduce){\n    var idx = 1;\n    setInterval(function(){ popHero(idx++); }, 4600);\n  }\n\n  /* \u5012\u8ba1\u65f6 \u2192 \u81ea\u52a8\u5237\u65b0 */\n  var left = 30, cd = document.getElementById('cd');\n  var t = setInterval(function(){\n    left--;\n    if (left<=0){ clearInterval(t); location.reload(); return; }\n    cd.textContent = left;\n  }, 1000);\n  document.getElementById('refresh').addEventListener('click', function(){ location.reload(); });\n})();\n</script>\n</body>\n</html>\n";

const DOWN_HEADERS = {
  'content-type': 'text/html; charset=utf-8',
  'cache-control': 'no-store',
  'x-down-page': '1'
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // 手动维护开关：设 MAINTENANCE=1 就永远显示宕机页
    if (env && env.MAINTENANCE === '1') {
      return maintenance();
    }

    const origin = (env && env.ORIGIN_URL) || 'https://blog-v3-virid.vercel.app';
    const upstream = new URL(url.pathname + url.search, origin);

    // 转发除 host 外的请求头（让源站识别成它自己的域名）
    const headers = new Headers(request.headers);
    headers.delete('host');

    try {
      const timeout = (env && Number(env.TIMEOUT_MS)) || 10000;
      const resp = await fetch(upstream, {
        method: request.method,
        headers,
        body: (request.method === 'GET' || request.method === 'HEAD') ? undefined : request.body,
        redirect: 'follow',
        signal: AbortSignal.timeout(timeout)
      });

      // 源站返回 5xx 视为宕机，给出维护页
      if (resp.status >= 500) {
        return maintenance();
      }

      // 正常：原样回传源站响应
      return new Response(resp.body, {
        status: resp.status,
        statusText: resp.statusText,
        headers: resp.headers
      });
    } catch (err) {
      // 源站连不上 / 超时 / TLS 出错 → 宕机页
      return maintenance();
    }
  }
};

function maintenance() {
  return new Response(MAINTENANCE, { status: 503, headers: DOWN_HEADERS });
}
